  void SetNavigation(string title){foreach(var p in navButtons){p.Value.Background=Color(p.Key==title?"#2466B0":"#142B44");p.Value.BorderBrush=p.Value.Background;p.Value.Foreground=p.Key==title?Brushes.White:Color("#DCE8F4");}}
  void Navigate(string destination){if(busy)return;if(destination!="视频与抽帧")StopPreview();if(destination=="视频与抽帧"||destination=="标注与审核"){tabs.SelectedIndex=destination=="视频与抽帧"?0:1;tabs.Visibility=Visibility.Visible;projectPage.Visibility=idsPage.Visibility=Visibility.Collapsed;SetNavigation(tabs.SelectedIndex==0?"视频与抽帧":"标注与审核");var list=tabs.SelectedIndex==0?videoFrames:frames;if(list.SelectedItem!=null)list.ScrollIntoView(list.SelectedItem);}else{tabs.Visibility=Visibility.Collapsed;projectPage.Visibility=destination=="项目"?Visibility.Visible:Visibility.Collapsed;idsPage.Visibility=destination=="IDS"?Visibility.Visible:Visibility.Collapsed;SetNavigation(destination);}}
