  static string FrameStateText(string value){switch(value){case "normal":return "正常";case "abnormal":return "异常";case "unknown":return "未知";default:return "未标注";}}
  void NavigateFrame(int direction){RequireFrame();int index=frames.SelectedIndex+direction;if(index<0||index>=frames.Items.Count)return;frames.SelectedIndex=index;frames.ScrollIntoView(frames.SelectedItem);}
  void UpdateFrameDetails(){if(frame==null){framePosition.Text="尚无图片";frameSummary.Text="等待抽帧";frameSource.Text="选择帧后显示来源";frameSource.ToolTip=null;previousFrame.IsEnabled=nextFrame.IsEnabled=saveNext.IsEnabled=markNormal.IsEnabled=false;return;}saveNext.IsEnabled=markNormal.IsEnabled=true;framePosition.Text=(frames.SelectedIndex+1)+" / "+frames.Items.Count;previousFrame.IsEnabled=frames.SelectedIndex>0;nextFrame.IsEnabled=frames.SelectedIndex+1<frames.Items.Count;var source=store.Find(frame.Text("video_id"));frameSource.Text="当前来源："+store.Find(source.Text("camera_id")).Text("name")+" / "+source.Text("original_name");frameSource.ToolTip=frameSource.Text;int confirmed=visibleConfirmedCount;frameSummary.Text="已确认 "+confirmed+" / "+frames.Items.Count;geometryDetails.Header="本帧标注 · "+Shapes().Count()+" 项";UpdateVideoStill();}
  void UpdateVideoFrames(){if(store==null)return;var video=videos.SelectedItem as Choice;syncFrames=true;videoFrames.ItemsSource=video==null?new List<Choice>():frames.Items.Cast<Choice>().Where(c=>store.Find(c.Id).Text("video_id")==video.Id).Select(c=>new Choice{Id=c.Id,Name=store.Find(video.Id).Text("original_name")+"\n"+c.Name}).ToList();videoFrames.SelectedItem=frame==null?null:videoFrames.Items.Cast<Choice>().FirstOrDefault(c=>c.Id==frame.id);if(videoFrames.SelectedItem==null&&videoFrames.Items.Count>0)videoFrames.SelectedIndex=0;syncFrames=false;videoCaption.Text=video==null?"选择源视频后可播放预览":store.Find(video.Id).Text("original_name");UpdateVideoStill();}
  void UpdateVideoStill(){var choice=videoFrames.SelectedItem as Choice;if(store==null||choice==null){videoStill.Source=null;return;}var f=store.Find(choice.Id);videoStill.Source=GetBitmap(f);}
  void PlayPreview(){Require();string id=Selected(videos);player.Source=new Uri(Rules.SafePath(store.Root,store.Find(id).Text("asset_path")));videoStill.Visibility=Visibility.Collapsed;player.Visibility=Visibility.Visible;player.Play();}
  void StopPreview(){player.Stop();player.Close();player.Source=null;player.Visibility=Visibility.Collapsed;videoStill.Visibility=Visibility.Visible;}
  void ShowHistory(){RequireFrame();string text=String.Join(Environment.NewLine+Environment.NewLine,store.Data.entities.Where(e=>e.kind=="Revision"&&(e.Text("entity_id")==frame.id||store.Data.entities.Any(a=>a.id==e.Text("entity_id")&&a.Text("frame_id")==frame.id))).Select(e=>e.Text("utc")+" / "+e.Text("actor")+Environment.NewLine+e.Text("snapshot")));new Window{Title="修改记录",Owner=this,Width=800,Height=500,Content=new TextBox{Text=text,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto}}.ShowDialog();}
 }
}
